// EmployeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from "../api/axios";   // your custom axios instance

const EmployeeDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);

  const [tickets, setTickets] = useState([]);

  useEffect(() => {
    const fetchTickets = async () => {
      try {
        const response = await api.get('tickets/');           // ← only this line changed!
        // filter tickets created by the logged-in user
        const myTickets = response.data.filter(
          ticket => ticket.creator?.id === user?.id
        );
        setTickets(myTickets);
      } catch (error) {
        console.log("Could not load your tickets:", error?.response?.data || error.message);
      }
    };

    if (user && token) fetchTickets();   // safe guard
  }, [token, user]);

  return (
    <div style={{ padding: '20px' }}>
      <h2>My Tickets</h2>

      {tickets.length === 0 ? (
        <p>You haven't created any tickets yet.</p>
      ) : (
        tickets.map(ticket => (
          <div
            key={ticket.id}
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              margin: '12px 0',
              padding: '16px',
              background: '#f9f9f9'
            }}
          >
            <h4>{ticket.title}</h4>
            <p><strong>Priority:</strong> {ticket.priority}</p>
            <p><strong>Status:</strong> {ticket.status}</p>
          </div>
        ))
      )}
    </div>
  );
};

export default EmployeeDashboard;
